import hashlib,json,os,pathlib,shutil,subprocess,sys,time
r=pathlib.Path.cwd(); out=r/'qa/evidence/failure-bundle-wiring'; work=r/'.work/independent-bundle'; work.mkdir(exist_ok=True); env=dict(os.environ,PYTHONPATH=str(r/'src'),PYTHONDONTWRITEBYTECODE='1'); results=[]
def run(label,args,cwd=r,environ=env):
 start=time.monotonic(); p=subprocess.run([sys.executable,*args],cwd=cwd,env=environ,capture_output=True,text=True,timeout=55); raw=p.stdout+p.stderr; (out/(label+'.log')).write_text(raw,encoding='utf-8'); results.append({'label':label,'command':[sys.executable,*args],'exit_code':p.returncode,'duration_s':time.monotonic()-start,'output_sha256':hashlib.sha256((out/(label+'.log')).read_bytes()).hexdigest()}); print(label,p.returncode,flush=True); return p,raw
nodes=['tests/test_run_failure_artifacts.py::'+n for n in ['test_launcher_bundles_sanitized_copies_and_reports','test_bundle_exception_preserves_functional_records','test_containment_and_uncertain_images_are_explicit','test_report_lookup_rejects_partial_corrupt_and_wrong_lineage']]
p,_=run('independent-focused',['-m','pytest',*nodes,'--basetemp',str(work/'baseline')]); assert p.returncode==0
copy=work/'mutation'; shutil.copytree(r/'src',copy/'src'); shutil.copytree(r/'tests',copy/'tests'); shutil.copy2(r/'pyproject.toml',copy/'pyproject.toml'); target=copy/'src/autotester/stages/run_artifacts.py'; original=target.read_bytes(); anchor=b'if index.run_id != run_id:'; assert original.count(anchor)==1; target.write_bytes(original.replace(anchor,b'if False:')); mutated=hashlib.sha256(target.read_bytes()).hexdigest(); menv=dict(env,PYTHONPATH=str(copy/'src'))
p,raw=run('independent-mutation-red',['-m','pytest',nodes[3],'--basetemp',str(work/'red')],copy,menv); assert p.returncode==1 and 'FAILED tests/test_run_failure_artifacts.py::test_report_lookup_rejects_partial_corrupt_and_wrong_lineage' in raw
finally_marker=True
target.write_bytes(original); assert target.read_bytes()==original
p,_=run('independent-mutation-restored',['-m','pytest',nodes[3],'--basetemp',str(work/'restored')],copy,menv); assert p.returncode==0
p,_=run('independent-ruff',['-m','ruff','check','src/autotester/schema/failure_bundle.py','src/autotester/stages/run_artifacts.py','src/autotester/stages/run_launcher.py','src/autotester/stages/report_export.py','tests/test_run_failure_artifacts.py']); assert p.returncode==0
p,_=run('independent-structure',['-c',"from pathlib import Path; from autotester.doctor import check_file_sizes,check_function_sizes,check_file_names,check_duplicate_definitions; r=Path.cwd(); v=[*check_file_sizes(r),*check_function_sizes(r),*check_file_names(r),*check_duplicate_definitions(r)]; print(*v,sep='\\n'); assert not v"]); assert p.returncode==0
(out/'independent-runtime.json').write_text(json.dumps({'results':results,'mutation_file':'src/autotester/stages/run_artifacts.py','mutation':'disable wrong-run index guard','original_sha256':hashlib.sha256(original).hexdigest(),'mutated_sha256':mutated,'restored_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'nodes':nodes},indent=2))
